const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'P(6,-2)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '6' },
      { kind: 'text', payload: '-2' },
      { kind: 'text', payload: '第四象限' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 720;
    var H = (input.viewport && input.viewport.heightDu) || 480;

    function metric(i, fw, fh) {
      var t = metrics && metrics[i];
      return { w: (t && t.width) || fw, h: (t && t.height) || fh };
    }
    var pMetrics = metric(0, 52, 16);

    var xMin = -1.6, xMax = 7.6, yMin = -3.6, yMax = 3.6;
    var mL = 64, mR = 44, mT = 40, mB = 56;
    var s = Math.min((W - mL - mR) / (xMax - xMin), (H - mT - mB) / (yMax - yMin));
    var plotW = (xMax - xMin) * s;
    var plotH = (yMax - yMin) * s;
    var ox = mL + (0 - xMin) * s + (W - mL - mR - plotW) / 2;
    var oy = mT + (yMax - 0) * s + (H - mT - mB - plotH) / 2;

    function X(x) { return ox + x * s; }
    function Y(y) { return oy - y * s; }

    function arrowHead(x, y, dx, dy, size, halfWidth) {
      var px = -dy, py = dx;
      var bx = x - dx * size, by = y - dy * size;
      return visualSdk.polyline([
        [x, y],
        [bx + px * halfWidth, by + py * halfWidth],
        [bx - px * halfWidth, by - py * halfWidth],
        [x, y]
      ]);
    }

    var xTipX = X(xMax - 0.15);
    var yTipY = Y(yMax - 0.15);
    var xLine = visualSdk.polyline([[X(xMin + 0.2), oy], [xTipX - 7, oy]]);
    var yLine = visualSdk.polyline([[ox, Y(yMin + 0.2)], [ox, yTipY + 7]]);
    var xHead = arrowHead(xTipX, oy, 1, 0, 10, 4);
    var yHead = arrowHead(ox, yTipY, 0, -1, 10, 4);

    var ticks = [];
    var i;
    for (i = Math.ceil(xMin + 0.2); i <= Math.floor(xMax - 0.2); i++) {
      if (i === 0) continue;
      ticks = ticks.concat(visualSdk.polyline([[X(i), oy - 4], [X(i), oy + 4]]));
    }
    for (i = Math.ceil(yMin + 0.2); i <= Math.floor(yMax - 0.2); i++) {
      if (i === 0) continue;
      ticks = ticks.concat(visualSdk.polyline([[ox - 4, Y(i)], [ox + 4, Y(i)]]));
    }

    function dashedLine(x1, y1, x2, y2, dash, gap) {
      var out = [];
      var dx = x2 - x1, dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len < 0.001) return out;
      var ux = dx / len, uy = dy / len;
      var t = 0;
      while (t < len) {
        var t2 = Math.min(t + dash, len);
        out = out.concat(visualSdk.polyline([
          [x1 + ux * t, y1 + uy * t],
          [x1 + ux * t2, y1 + uy * t2]
        ]));
        t += dash + gap;
      }
      return out;
    }

    var px = X(6), py = Y(-2);
    var dashV = dashedLine(px, Y(0), px, py, 7, 5);
    var dashH = dashedLine(X(0), py, px, py, 7, 5);
    var point = visualSdk.circle(px, py, 4.8);

    var labels = [
      { type: 'label', x: px, y: py + Math.max(16, pMetrics.h + 6), text: 'P(6,-2)', fontSize: 16, fill: '#c0392b', align: 'center', baseline: 'middle' },
      { type: 'label', x: X(xMax - 0.1) + 7, y: oy - 13, text: 'x', fontSize: 18, fill: '#26354a', align: 'left', baseline: 'middle' },
      { type: 'label', x: ox + 14, y: Y(yMax - 0.1) - 11, text: 'y', fontSize: 18, fill: '#26354a', align: 'left', baseline: 'middle' },
      { type: 'label', x: ox - 12, y: oy + 17, text: 'O', fontSize: 16, fill: '#26354a', align: 'right', baseline: 'middle' },
      { type: 'label', x: X(6) + 8, y: oy + 16, text: '6', fontSize: 16, fill: '#26354a', align: 'left', baseline: 'middle' },
      { type: 'label', x: ox - 12, y: Y(-2), text: '-2', fontSize: 16, fill: '#26354a', align: 'right', baseline: 'middle' },
      { type: 'label', x: X(3.4), y: Y(-1.2), text: '第四象限', fontSize: 16, fill: '#2c7fb8', align: 'center', baseline: 'middle' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'fig-point-p-6-neg2-quadrant-iv',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xaxis', commands: xLine },
        { id: 'yaxis', commands: yLine },
        { id: 'xhead', commands: xHead },
        { id: 'yhead', commands: yHead },
        { id: 'ticks', commands: ticks },
        { id: 'dashV', commands: dashV },
        { id: 'dashH', commands: dashH },
        { id: 'point', commands: point }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ticks', stroke: '#95a5a6', strokeWidth: 1, fill: 'none' },
          { type: 'path', pathId: 'xaxis', stroke: '#26354a', strokeWidth: 1.6, fill: 'none' },
          { type: 'path', pathId: 'yaxis', stroke: '#26354a', strokeWidth: 1.6, fill: 'none' },
          { type: 'path', pathId: 'xhead', fill: '#26354a', stroke: '#26354a', strokeWidth: 1 },
          { type: 'path', pathId: 'yhead', fill: '#26354a', stroke: '#26354a', strokeWidth: 1 },
          { type: 'path', pathId: 'dashV', stroke: '#2c7fb8', strokeWidth: 1.4, fill: 'none' },
          { type: 'path', pathId: 'dashH', stroke: '#2c7fb8', strokeWidth: 1.4, fill: 'none' },
          { type: 'path', pathId: 'point', fill: '#c0392b', stroke: '#c0392b', strokeWidth: 1 }
        ].concat(labels)
      }
    };
  }
};
